<script lang="ts">
  import { onMount } from "svelte";
  import type { LlamaCppBuildDetails, LlamaCppBuildListResponse, LlamaBuildDiscoveryResponse, RouterRuntimeResponse } from "@obsidianlm/shared";
  import PageHeader from "../components/PageHeader.svelte";
  import BuildInspector from "../components/BuildInspector.svelte";
  import { API_ENDPOINTS, fetchJson } from "../api";
  let mode: "registered" | "discovery" = "registered", builds: LlamaCppBuildDetails[] = [], discovery: LlamaBuildDiscoveryResponse["builds"] = [], runtime: RouterRuntimeResponse | null = null, selected: string | null = null, message = "", query = "", eligibility = "all";
  $: build = builds.find((entry) => entry.id === selected) ?? null;
  $: buildRows = builds.filter((entry) => `${entry.displayName} ${entry.classification} ${entry.versionInfo?.raw ?? ""}`.toLowerCase().includes(query.toLowerCase()) && (eligibility === "all" || entry.managedInferenceEligibility === eligibility));
  $: discoveryRows = discovery.filter((entry) => `${entry.name} ${entry.serverPath}`.toLowerCase().includes(query.toLowerCase()));
  async function load() { message = ""; try { const registered = await fetchJson<LlamaCppBuildListResponse>(API_ENDPOINTS.builds.list); builds = registered.builds; const [found, router] = await Promise.allSettled([fetchJson<LlamaBuildDiscoveryResponse>(API_ENDPOINTS.discovery.llamaBuilds), fetchJson<RouterRuntimeResponse>(API_ENDPOINTS.runtime.state)]); discovery = found.status === "fulfilled" ? found.value.builds : []; runtime = router.status === "fulfilled" ? router.value : null; if (found.status === "rejected" || router.status === "rejected") message = "Discovery or runtime status is unavailable; registered builds remain available."; } catch (error) { message = error instanceof Error ? error.message : "Could not load registered builds."; } }
  async function register(discoveryId: string) { try { await fetchJson(API_ENDPOINTS.builds.register, { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ discoveryId }) }); message = "Build registered."; await load(); } catch (error) { message = error instanceof Error ? error.message : "Registration failed."; } }
  async function rescan() { try { await fetchJson(API_ENDPOINTS.discovery.rescanLlamaBuilds, { method: "POST" }); message = "Build discovery rescanned."; await load(); } catch (error) { message = error instanceof Error ? error.message : "Rescan failed."; } }
  function registered(candidate: LlamaBuildDiscoveryResponse["builds"][number]) { return builds.find((entry) => entry.discoveryId === candidate.id); }
  onMount(() => { void load(); });
</script>

<main class="page-surface builds-page" aria-label="Builds"><PageHeader title="Builds" subtitle="Registered Builds are authoritative; discovery candidates require explicit registration." />
  <div class="actions" role="group" aria-label="Build views"><button class:primary={mode === "registered"} class="btn" type="button" aria-pressed={mode === "registered"} on:click={() => { mode = "registered"; selected = null; }}>Registered Builds</button><button class:primary={mode === "discovery"} class="btn" type="button" aria-pressed={mode === "discovery"} on:click={() => { mode = "discovery"; selected = null; }}>Discovery</button><span role="status">{message}</span></div>
  <div class="filters"><label>Search <input bind:value={query} placeholder="Name, classification, version" /></label>{#if mode === "registered"}<label>Eligibility <select bind:value={eligibility}><option value="all">All</option><option value="eligible">Eligible</option><option value="ineligible">Ineligible</option><option value="not_validated">Not validated</option><option value="failed">Failed</option><option value="unknown">Unknown</option></select></label>{:else}<button class="btn" type="button" on:click={rescan}>Rescan discovery</button>{/if}</div>
  <div class="layout"><section class="panel list" aria-label={mode === "registered" ? "Registered Builds" : "Build discovery candidates"}>{#if mode === "registered"}<div class="table registered-table" role="table" aria-label="Registered Builds"><div class="head" role="row"><span>Name</span><span>Classification</span><span>Version</span><span>Eligibility</span><span>Configured Models</span><span>Tools</span><span>Active</span></div>{#each buildRows as item}<button class:active={selected === item.id} class="row" type="button" role="row" on:click={() => selected = item.id}><strong>{item.displayName}</strong><span>{item.classification}</span><span>{item.versionInfo?.raw ?? "Unknown"}</span><span>{item.managedInferenceEligibility}</span><span>{item.configuredModelIds.length}</span><span>{item.tools.length}</span><span>{runtime?.routerState.activeBuildId === item.id ? "Yes" : "No"}</span></button>{:else}<p class="empty-state">No registered builds match these filters.</p>{/each}</div>{:else}<div class="table discovery-table" role="table" aria-label="Build discovery candidates"><div class="head" role="row"><span>Name</span><span>Server</span><span>Tools</span><span>Registration</span></div>{#each discoveryRows as item}<button class:active={selected === `discovery:${item.id}`} class="row" type="button" role="row" on:click={() => selected = `discovery:${item.id}`}><strong>{item.name}</strong><span>{item.serverPath}</span><span>{item.tools.length}</span><span>{registered(item) ? `Registered: ${registered(item)?.displayName}` : "Candidate"}</span></button>{:else}<p class="empty-state">No discovery candidates match this search.</p>{/each}</div>{/if}</section>
    {#if build}<BuildInspector {build} {runtime} onChanged={load} />{:else}<aside class="panel inspector"><h2 class="section-title">Build inspector</h2>{#if selected?.startsWith("discovery:")}{#if registered(discovery.find((item) => item.id === selected?.slice(10))!)}<p>This candidate is already registered.</p>{:else}<p>Discovery candidate. Registration captures a stable Build record.</p><button class="btn primary" type="button" on:click={() => register(selected!.slice(10))}>Register build</button>{/if}{:else}<p class="empty-state">Select a build.</p>{/if}</aside>{/if}
  </div>
</main>

<style>
  .actions,.filters{display:flex;flex-wrap:wrap;gap:.5rem;align-items:center;margin-bottom:.75rem}.actions span{color:var(--color-muted)}.filters label{display:grid;gap:.2rem;font-size:.82rem}.layout{display:grid;grid-template-columns:minmax(0,1fr) minmax(18rem,30rem);gap:1rem}.list{overflow:auto}.table{min-width:48rem}.head,.row{display:grid;grid-template-columns:1.35fr 1fr 1.2fr 1fr .9fr .55fr .55fr;gap:.6rem;align-items:center;padding:.65rem .75rem}.discovery-table .head,.discovery-table .row{grid-template-columns:1fr 2fr .55fr 1fr}.head{font-size:.75rem;color:var(--color-muted);border-bottom:1px solid var(--color-line)}.row{width:100%;text-align:left;color:inherit;background:transparent;border:0;border-bottom:1px solid var(--color-line)}.row:hover,.row.active{background:var(--color-panel-strong)}.row span,.row strong{overflow-wrap:anywhere}.inspector{padding:1rem;min-width:0}@media(max-width:900px){.layout{grid-template-columns:1fr}.builds-page{min-width:0;overflow-x:hidden}.list{max-width:100%}}@media(max-width:320px){.filters input,.filters select{max-width:100%}.inspector{min-width:0}}
</style>
